with filtered_inventory as (select * from inventory where product_id in (2, 9)), store_id_summary as (select store_id, case when quantity >= 222 then 'high' when quantity >= 82 then 'mid' else 'low' end as quantity_bucket, round(avg(quantity), 2) as avg_quantity, count(quantity) as quantity_count from filtered_inventory group by store_id, case when quantity >= 222 then 'high' when quantity >= 82 then 'mid' else 'low' end) select store_id, quantity_bucket, avg_quantity, quantity_count from store_id_summary where avg_quantity < 27 order by store_id
